module turtle_drawing_solver(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] target_grid,\n    input wire [255:0] commands,\n    output reg [7:0] earliest,\n    output reg [7:0] latest,\n    output reg done\n);\n\n    // State definitions\n    localparam [5:0] IDLE = 6'd0;\n    localparam [5:0] RESET = 6'd1;\n    localparam [5:0] START_DRAW = 6'd2;\n    localparam [5:0] EXECUTE_CMD = 6'd3;\n    localparam [5:0] NEXT_CMD = 6'd4;\n    localparam [5:0] CHECK_RESULT = 6'd5;\n    localparam [5:0] DONE_STATE = 6'd6;\n\n    reg [5:0] state, next_state;\n    reg [7:0] current_time;\n    reg [2:0] pos_x, pos_y;\n    reg [63:0] drawn_grid;\n    reg [7:0] cmd_index;\n    reg [5:0] step_counter;\n    reg [1:0] direction;\n    reg [5:0] distance;\n    reg [2:0] new_x, new_y;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            earliest <= 8'd0;\n            latest <= 8'd0;\n            current_time <= 8'd0;\n            drawn_grid <= 64'd0;\n            cmd_index <= 8'd0;\n            step_counter <= 6'd0;\n            pos_x <= 3'd0;\n            pos_y <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start)\n                        state <= RESET;\n                end\n\n                RESET: begin\n                    drawn_grid <= 64'd0;\n                    current_time <= 8'd0;\n                    cmd_index <= 8'd0;\n                    step_counter <= 6'd0;\n                    pos_x <= 3'd0;\n                    pos_y <= 3'd0;\n                    state <= START_DRAW;\n                end\n\n                START_DRAW: begin\n                    drawn_grid <= drawn_grid | (64'd1 << (pos_y * 8 + pos_x));\n                    current_time <= current_time + 8'd1;\n                    state <= EXECUTE_CMD;\n                end\n\n                EXECUTE_CMD: begin\n                    if (cmd_index < 8'd32) begin\n                        if (step_counter < distance) begin\n                            new_x = pos_x;\n                            new_y = pos_y;\n                            case (direction)\n                                2'b00: new_y = (pos_y < 3'd7) ? pos_y + 3'd1 : 3'd7;\n                                2'b01: new_y = (pos_y > 3'd0) ? pos_y - 3'd1 : 3'd0;\n                                2'b10: new_x = (pos_x > 3'd0) ? pos_x - 3'd1 : 3'd0;\n                                2'b11: new_x = (pos_x < 3'd7) ? pos_x + 3'd1 : 3'd7;\n                            endcase\n                            pos_x <= new_x;\n                            pos_y <= new_y;\n                            drawn_grid <= drawn_grid | (64'd1 << (new_y * 8 + new_x));\n                            current_time <= current_time + 8'd1;\n                            step_counter <= step_counter + 6'd1;\n                        end else begin\n                            step_counter <= 6'd0;\n                            state <= NEXT_CMD;\n                        end\n                    end else begin\n                        state <= CHECK_RESULT;\n                    end\n                end\n\n                NEXT_CMD: begin\n                    cmd_index <= cmd_index + 8'd1;\n                    state <= EXECUTE_CMD;\n                end\n\n                CHECK_RESULT: begin\n                    if (drawn_grid == target_grid) begin\n                        earliest <= current_time - 8'd1;\n                        latest <= current_time - 8'd1;\n                    end else begin\n                        earliest <= 8'd255;\n                        latest <= 8'd255;\n                    end\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    always @(*) begin\n        if (state == EXECUTE_CMD && cmd_index < 8'd32) begin\n            // Extract direction and distance from command\n            direction = commands[cmd_index*8 +: 2];\n            distance = commands[cmd_index*8 +2 +:6];\n        end else begin\n            direction = 2'b00;\n            distance = 6'b0;\n        end\n    end\n\nendmodule